<template>
  <section class="group-panel" aria-label="群组列表与群详情">
    <template v-if="!selectedGroup">
      <div class="group-toolbar">
        <label class="group-search"><i class="fa fa-search"></i><input v-model="keyword" placeholder="搜索群名称" /></label>
        <button title="创建群聊" aria-label="创建群聊" @click="$emit('create')"><i class="fa fa-plus"></i></button>
      </div>
      <div class="group-filter"><button :class="{active:filter==='all'}" @click="filter='all'">全部 {{ groups.length }}</button><button :class="{active:filter==='pinned'}" @click="filter='pinned'">置顶</button><button :class="{active:filter==='recent'}" @click="filter='recent'">最近活跃</button><button disabled title="需要群号/邀请链接服务端接口">加入群聊</button></div>
      <p class="group-note"><i class="fa fa-refresh"></i> 群资料与成员变更每 30 秒同步；聊天消息实时通过 IM V2 通道到达。</p>
      <div v-if="loading" class="group-loading"><i class="fa fa-circle-o-notch fa-spin"></i> 正在加载群组</div>
      <template v-else-if="filteredGroups.length">
        <div v-if="filter==='all' && filteredGroups.some(item=>item.pinned)" class="section-label">置顶群组</div>
        <button v-for="group in filteredGroups" :key="group.groupId" class="group-row" @click="openDetail(group.groupId)" @dblclick="$emit('open-group',group.groupId)" @contextmenu.prevent="openDetail(group.groupId)">
          <span class="group-avatar"><img v-if="group.avatar" :src="group.avatar" alt="" /><b v-else><i class="fa fa-users"></i></b></span>
          <div><strong><i v-if="group.pinned" class="fa fa-thumb-tack"></i>{{ group.groupName }}</strong><small>{{ group.lastMessage || '暂无消息' }}</small><em>{{ group.memberCount }} 人 · {{ relativeTime(group.lastMessageTime) }}</em></div>
          <aside><i v-if="group.muted" class="fa fa-volume-off"></i><b v-else-if="group.unread">{{ group.unread>99?'99+':group.unread }}</b></aside>
        </button>
      </template>
      <div v-else class="group-empty"><i class="fa fa-users"></i><strong>{{ keyword ? '没有匹配的群聊' : '还没有加入群聊' }}</strong><span>{{ keyword ? '试试其他群名称关键词。' : '创建一个项目群，与好友开始协作。' }}</span><button v-if="!keyword" @click="$emit('create')">创建群聊</button></div>
    </template>

    <template v-else>
      <div class="detail-topbar"><button @click="selectedGroup=null"><i class="fa fa-angle-left"></i> 群组列表</button><button @click="refreshDetail"><i class="fa fa-refresh" :class="{ 'fa-spin': detailLoading }"></i></button></div>
      <div v-if="detailLoading" class="group-loading"><i class="fa fa-circle-o-notch fa-spin"></i> 正在同步群详情</div>
      <template v-else-if="detail">
        <div class="group-profile">
          <span class="large-group-avatar"><img v-if="detail.avatar" :src="detail.avatar" alt="" /><i v-else class="fa fa-users"></i></span>
          <h3>{{ detail.groupName }}</h3><button class="copy-id" @click="copyGroupId"><i class="fa fa-copy"></i> 群 ID：{{ detail.groupId }}</button>
          <small>{{ detail.memberCount }}/{{ detail.maxMembers }} 人 · {{ roleName(detail.currentUserRole) }}</small>
          <div class="group-actions"><button class="primary" @click="$emit('open-group',detail.groupId)"><i class="fa fa-commenting-o"></i> 进入聊天</button><button v-if="canManage" @click="inviteOpen=true"><i class="fa fa-user-plus"></i> 邀请成员</button><button v-if="!isOwner" class="danger" @click="leave"><i class="fa fa-sign-out"></i> 退出群聊</button><button v-else class="danger" @click="dissolve"><i class="fa fa-trash-o"></i> 解散群聊</button></div>
        </div>

        <section class="group-edit-card">
          <header><strong>群资料</strong><button v-if="canManage" @click="editing=!editing">{{ editing?'取消':'编辑' }}</button></header>
          <template v-if="editing"><label>群名称<input v-model="editName" maxlength="30" /></label><label>群头像地址 <input v-model="editAvatar" placeholder="文件服务返回的可访问 URL" /></label><label>群公告<textarea v-model="editAnnouncement" maxlength="500" placeholder="暂无群公告"></textarea></label><button class="primary save-group" :disabled="saving" @click="saveGroup">保存群资料</button></template>
          <template v-else><p v-if="detail.announcement">{{ detail.announcement }}</p><p v-else class="muted">暂无群公告</p><small v-if="detail.description">{{ detail.description }}</small></template>
        </section>

        <section class="members-card">
          <header><strong>群成员（{{ detail.memberCount }}）</strong><label><i class="fa fa-search"></i><input v-model="memberKeyword" placeholder="搜索成员" /></label></header>
          <div class="member-grid">
            <article v-for="member in filteredMembers" :key="member.userId" class="member-card">
              <span><img v-if="member.avatar" :src="member.avatar" alt="" /><b v-else>{{ memberLabel(member).slice(0,1) }}</b></span><div><strong>{{ memberLabel(member) }}</strong><small :class="{ muted: isMuted(member) }">{{ roleName(member.role) }}{{ isMuted(member)?' · 已禁言':'' }}</small></div>
              <button v-if="canManage && member.userId!==currentUserId" class="member-more" @click="manageMember=manageMember===member.userId?'':member.userId"><i class="fa fa-ellipsis-h"></i></button>
              <div v-if="manageMember===member.userId" class="member-menu"><button @click="$emit('open-private',member.userId)">发消息</button><button v-if="isOwner && member.role!==1" @click="setRole(member,member.role===2?3:2)">{{ member.role===2?'取消管理员':'设为管理员' }}</button><button v-if="!isMuted(member)" @click="muteMember(member)">禁言 60 分钟</button><button v-else @click="unmuteMember(member)">取消禁言</button><button class="danger" @click="removeMember(member)">移出群聊</button></div>
            </article>
          </div>
          <button v-if="membersHasMore" class="load-members" @click="loadMembers(memberPage+1)">加载更多成员</button>
        </section>
      </template>
      <div v-else class="group-empty"><i class="fa fa-exclamation-circle"></i><strong>群详情不可用</strong><button @click="selectedGroup=null">返回列表</button></div>
    </template>

    <dialog :open="inviteOpen" class="invite-dialog" @click.self="inviteOpen=false"><header><strong>邀请好友加入群聊</strong><button @click="inviteOpen=false"><i class="fa fa-times"></i></button></header><label class="group-search"><i class="fa fa-search"></i><input v-model="inviteKeyword" placeholder="搜索好友" /></label><div class="invite-list"><label v-for="friend in inviteCandidates" :key="friend.friendId"><input v-model="selectedInvitees" type="checkbox" :value="friend.friendId" /><span>{{ friend.remark||friend.username||friend.account||friend.friendId }}</span></label></div><footer><span>已选择 {{ selectedInvitees.length }} 人</span><button class="primary" :disabled="!selectedInvitees.length||saving" @click="invite">发送邀请</button></footer></dialog>
  </section>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { GroupDTO, GroupMemberDTO } from '@/api/im/types'
import type { MessageCenterFriend, MessageCenterGroup } from '@/stores/messageCenterStore'
import { GroupRole } from '@/api/im/types'
import { getGroupApi, inviteGroupMembersApi, listGroupMembersApi, muteGroupMemberApi, removeGroupMemberApi, setGroupMemberRoleApi, unmuteGroupMemberApi, updateGroupApi } from '@/api/im/groupApi'

const props=defineProps<{groups:MessageCenterGroup[];friends:MessageCenterFriend[];currentUserId:string;loading?:boolean;activeGroupId?:string}>()
const emit=defineEmits<{create:[];'open-group':[groupId:string];'open-private':[userId:string];'leave':[groupId:string];dissolve:[groupId:string];changed:[];toast:[message:string,error?:boolean]}>()
const keyword=ref(''),filter=ref<'all'|'pinned'|'recent'>('all'),selectedGroup=ref<string|null>(null),detail=ref<GroupDTO|null>(null),members=ref<GroupMemberDTO[]>([]),detailLoading=ref(false),saving=ref(false),memberPage=ref(1),membersHasMore=ref(false),memberKeyword=ref(''),editing=ref(false),editName=ref(''),editAvatar=ref(''),editAnnouncement=ref(''),inviteOpen=ref(false),inviteKeyword=ref(''),selectedInvitees=ref<string[]>([]),manageMember=ref('')
const filteredGroups=computed(()=>props.groups.filter(group=>{const matches=!keyword.value||group.groupName.toLowerCase().includes(keyword.value.toLowerCase());return matches&&(filter.value==='all'||filter.value==='pinned'&&group.pinned||filter.value==='recent'&&!group.pinned)}))
const isOwner=computed(()=>detail.value?.currentUserRole===GroupRole.OWNER)
const canManage=computed(()=>detail.value?.currentUserRole===GroupRole.OWNER||detail.value?.currentUserRole===GroupRole.ADMIN)
const filteredMembers=computed(()=>members.value.filter(member=>!memberKeyword.value||memberLabel(member).toLowerCase().includes(memberKeyword.value.toLowerCase())))
const inviteCandidates=computed(()=>props.friends.filter(friend=>!inviteKeyword.value||`${friend.remark||''} ${friend.username||''} ${friend.account||''}`.toLowerCase().includes(inviteKeyword.value.toLowerCase())))
watch(()=>props.activeGroupId,id=>{if(id)openDetail(id)})
function relativeTime(value:number){const delta=Math.max(0,Date.now()-value);if(delta<60_000)return'刚刚';if(delta<3_600_000)return`${Math.floor(delta/60_000)} 分钟前`;if(delta<86_400_000)return`${Math.floor(delta/3_600_000)} 小时前`;return new Date(value).toLocaleDateString('zh-CN')}
function roleName(role?:number){return role===1?'群主':role===2?'管理员':'成员'}
function memberLabel(member:GroupMemberDTO){return member.alias||member.nickname||member.userId}
function isMuted(member:GroupMemberDTO){return Boolean(member.muteUntil&&new Date(member.muteUntil).getTime()>Date.now())}
async function openDetail(groupId:string){selectedGroup.value=groupId;await refreshDetail()}
async function refreshDetail(){if(!selectedGroup.value)return;detailLoading.value=true;try{const [groupResponse,membersResponse]=await Promise.all([getGroupApi(selectedGroup.value,props.currentUserId),listGroupMembersApi(selectedGroup.value,props.currentUserId,1,100)]);if(groupResponse.code!==200||!groupResponse.data)throw new Error(groupResponse.message||'群详情加载失败');detail.value=groupResponse.data;editName.value=detail.value.groupName;editAvatar.value=detail.value.avatar||'';editAnnouncement.value=detail.value.announcement||'';if(membersResponse.code!==200)throw new Error(membersResponse.message||'群成员加载失败');members.value=membersResponse.data?.items||[];memberPage.value=1;membersHasMore.value=membersResponse.data?.hasMore||false}catch(error){detail.value=null;emit('toast',error instanceof Error?error.message:'群详情加载失败',true)}finally{detailLoading.value=false}}
async function loadMembers(page:number){if(!selectedGroup.value)return;const response=await listGroupMembersApi(selectedGroup.value,props.currentUserId,page,100);if(response.code!==200){emit('toast',response.message||'成员加载失败',true);return}members.value=[...members.value,...(response.data?.items||[])];memberPage.value=page;membersHasMore.value=response.data?.hasMore||false}
async function saveGroup(){if(!detail.value)return;saving.value=true;try{const response=await updateGroupApi(detail.value.groupId,{operatorId:props.currentUserId,name:editName.value.trim(),avatarFileId:editAvatar.value.trim()||undefined,announcement:editAnnouncement.value.trim()});if(response.code!==200||!response.data)throw new Error(response.message||'群资料保存失败');detail.value=response.data;editing.value=false;emit('changed');emit('toast','群资料已保存')}catch(error){emit('toast',error instanceof Error?error.message:'群资料保存失败',true)}finally{saving.value=false}}
async function invite(){if(!detail.value)return;saving.value=true;try{const response=await inviteGroupMembersApi(detail.value.groupId,props.currentUserId,selectedInvitees.value);if(response.code!==200)throw new Error(response.message||'邀请失败');inviteOpen.value=false;selectedInvitees.value=[];await refreshDetail();emit('changed');emit('toast','已邀请成员加入群聊')}catch(error){emit('toast',error instanceof Error?error.message:'邀请失败',true)}finally{saving.value=false}}
async function removeMember(member:GroupMemberDTO){if(!detail.value||!confirm(`确定将 ${memberLabel(member)} 移出群聊吗？`))return;const response=await removeGroupMemberApi(detail.value.groupId,props.currentUserId,member.userId);if(response.code!==200){emit('toast',response.message||'移除成员失败',true);return}manageMember.value='';await refreshDetail();emit('changed');emit('toast','已移出群成员')}
async function setRole(member:GroupMemberDTO,role:GroupRole){if(!detail.value)return;const response=await setGroupMemberRoleApi(detail.value.groupId,member.userId,props.currentUserId,role);if(response.code!==200){emit('toast',response.message||'角色更新失败',true);return}manageMember.value='';await refreshDetail();emit('changed');emit('toast','成员角色已更新')}
async function muteMember(member:GroupMemberDTO){if(!detail.value)return;const response=await muteGroupMemberApi(detail.value.groupId,member.userId,props.currentUserId,60);if(response.code!==200){emit('toast',response.message||'禁言失败',true);return}manageMember.value='';await refreshDetail();emit('changed');emit('toast','已禁言 60 分钟')}
async function unmuteMember(member:GroupMemberDTO){if(!detail.value)return;const response=await unmuteGroupMemberApi(detail.value.groupId,member.userId,props.currentUserId);if(response.code!==200){emit('toast',response.message||'取消禁言失败',true);return}manageMember.value='';await refreshDetail();emit('changed');emit('toast','已取消禁言')}
async function copyGroupId(){if(!detail.value)return;try{await navigator.clipboard.writeText(detail.value.groupId);emit('toast','群 ID 已复制')}catch{emit('toast','当前浏览器不允许复制',true)}}
function leave(){if(detail.value&&confirm('退出后历史会话仍可查看，但无法继续发送消息。确定退出吗？')){emit('leave',detail.value.groupId);selectedGroup.value=null}}
function dissolve(){if(detail.value&&confirm('解散后所有成员均不能继续发送消息，历史会话会保留为只读。确定解散吗？')){emit('dissolve',detail.value.groupId);selectedGroup.value=null}}
</script>

<style scoped>
.group-panel{height:100%;min-height:0;overflow:auto;padding:14px;position:relative}.group-toolbar,.detail-topbar{display:flex;gap:7px}.group-search{height:38px;min-width:0;flex:1;display:flex;align-items:center;gap:7px;padding:0 10px;border-radius:10px;background:var(--im-input);color:var(--im-muted)}.group-search input{min-width:0;flex:1;background:transparent;color:var(--im-text);outline:0}.group-toolbar>button,.detail-topbar>button{width:38px;border-radius:9px;background:var(--im-accent-soft);color:var(--im-accent)}.group-filter{display:flex;gap:3px;margin:10px 0;overflow:auto}.group-filter button{padding:5px 7px;border-radius:8px;color:var(--im-muted);white-space:nowrap;font-size:11px}.group-filter button.active{background:var(--im-selected);color:var(--im-accent)}.group-filter button:disabled{opacity:.6}.group-note{display:flex;gap:6px;padding:8px;border-radius:9px;background:var(--im-accent-soft);color:var(--im-muted);font-size:10px;line-height:1.45}.section-label{margin-top:10px;padding:5px 3px;color:var(--im-muted);font-size:11px}.group-row{width:100%;min-height:66px;display:flex;align-items:center;gap:9px;padding:8px 5px;border-bottom:1px solid var(--im-border);text-align:left;color:var(--im-text)}.group-row:hover{background:var(--im-hover)}.group-avatar,.large-group-avatar{display:grid;place-items:center;overflow:hidden;background:linear-gradient(135deg,var(--im-accent),#8b5cf6);color:#fff}.group-avatar{width:43px;height:43px;flex:0 0 auto;border-radius:13px}.group-avatar img,.large-group-avatar img{width:100%;height:100%;object-fit:cover}.group-row>div{min-width:0;flex:1;display:flex;flex-direction:column}.group-row strong,.group-row small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.group-row strong i{margin-right:4px;color:var(--im-accent);font-size:10px}.group-row small,.group-row em{color:var(--im-muted);font-size:10px;font-style:normal}.group-row aside{width:30px;display:grid;justify-items:end;color:var(--im-muted)}.group-row aside b{min-width:18px;padding:2px 4px;border-radius:9px;background:#e5484d;color:#fff;text-align:center;font-size:9px}.group-empty,.group-loading{min-height:210px;display:grid;place-content:center;justify-items:center;gap:9px;color:var(--im-muted);text-align:center;font-size:12px}.group-empty>i{font-size:38px;opacity:.4}.group-empty strong{color:var(--im-text)}.group-empty button{margin-top:4px;padding:8px 12px;border-radius:9px;background:var(--im-accent);color:#fff}.detail-topbar{justify-content:space-between;margin-bottom:10px}.detail-topbar>button:first-child{width:auto;padding:0 8px;background:transparent;color:var(--im-muted)}.group-profile{display:grid;justify-items:center;text-align:center}.large-group-avatar{width:76px;height:76px;border-radius:24px;font-size:31px}.group-profile h3{margin-top:8px;font-size:18px}.copy-id{margin-top:3px;color:var(--im-muted);font-size:11px}.group-profile small{margin-top:5px;color:var(--im-muted);font-size:11px}.group-actions{width:100%;display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin:14px 0}.group-actions button,.save-group{min-height:36px;padding:7px;border-radius:9px;background:var(--im-input);color:var(--im-text);font-size:11px}.group-actions .primary,.primary{background:var(--im-accent);color:#fff}.group-actions .danger{color:#d33b43}.group-edit-card,.members-card{margin-top:12px;padding:10px;border:1px solid var(--im-border);border-radius:12px}.group-edit-card header,.members-card header{display:flex;align-items:center;justify-content:space-between;gap:8px}.group-edit-card header button{color:var(--im-accent);font-size:11px}.group-edit-card p{margin-top:9px;white-space:pre-wrap;line-height:1.5;font-size:12px}.group-edit-card small,.muted{color:var(--im-muted)}.group-edit-card label{display:grid;gap:4px;margin-top:8px;color:var(--im-muted);font-size:11px}.group-edit-card input,.group-edit-card textarea{width:100%;padding:7px;border-radius:8px;background:var(--im-input);color:var(--im-text);outline:0}.group-edit-card textarea{min-height:66px;resize:vertical}.save-group{width:100%;margin-top:8px}.members-card header .group-search{height:30px;max-width:140px;font-size:10px}.member-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:10px}.member-card{position:relative;min-width:0;display:flex;align-items:center;gap:6px;padding:6px;border-radius:9px;background:var(--im-input)}.member-card>span{width:30px;height:30px;flex:0 0 auto;display:grid;place-items:center;overflow:hidden;border-radius:50%;background:var(--im-avatar);font-size:11px}.member-card>span img{width:100%;height:100%;object-fit:cover}.member-card>div{min-width:0;display:flex;flex:1;flex-direction:column}.member-card strong,.member-card small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px}.member-card small{color:var(--im-muted)}.member-more{width:22px;color:var(--im-muted)}.member-menu{position:absolute;z-index:5;right:4px;top:38px;width:106px;padding:4px;border:1px solid var(--im-border);border-radius:8px;background:var(--im-panel);box-shadow:var(--im-shadow)}.member-menu button{display:block;width:100%;padding:5px;color:var(--im-text);text-align:left;font-size:10px}.member-menu .danger{color:#d33b43}.load-members{width:100%;margin-top:8px;padding:7px;border-radius:8px;background:var(--im-input);color:var(--im-accent);font-size:11px}.invite-dialog{inset:10% 12px auto;width:min(360px,calc(100vw - 24px));max-height:78dvh;padding:14px;border:1px solid var(--im-border);border-radius:14px;background:var(--im-panel);color:var(--im-text);box-shadow:var(--im-shadow)}.invite-dialog::backdrop{background:#0007}.invite-dialog header,.invite-dialog footer{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.invite-list{max-height:300px;overflow:auto;margin-top:8px}.invite-list label{display:flex;align-items:center;gap:8px;padding:8px;border-bottom:1px solid var(--im-border);font-size:12px}.invite-dialog footer{margin:10px 0 0;color:var(--im-muted);font-size:11px}.invite-dialog footer button{padding:7px 10px;border-radius:8px}@media(max-width:420px){.member-grid{grid-template-columns:1fr}.group-actions{grid-template-columns:1fr}.group-panel{padding:10px}}
</style>
